import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BS0bAV7E.js";const h=JSON.parse('{"title":"L1 指南：块设备驱动","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/driver-block.md","filePath":"zh/l1/driver-block.md"}'),s={name:"zh/l1/driver-block.md"};function o(r,e,d,c,n,p){return i(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="l1-指南-块设备驱动" tabindex="-1">L1 指南：块设备驱动 <a class="header-anchor" href="#l1-指南-块设备驱动" aria-label="Permalink to &quot;L1 指南：块设备驱动&quot;">​</a></h1><p>注册一个存储设备，使整个系统（VFS、分区、文件系统工具）都能识别它。</p><h2 id="接口面" tabindex="-1">接口面 <a class="header-anchor" href="#接口面" aria-label="Permalink to &quot;接口面&quot;">​</a></h2><p><code>drivers/block/driver_block_blk.h</code>（17 个声明；编号为 8 的）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>driver_block_register(name, ops, ctx)     -&gt; device id</span></span>
<span class="line"><span>driver_block_read(dev, lba, count, buf)   -&gt; bytes read / &lt;0</span></span>
<span class="line"><span>driver_block_write(dev, lba, count, buf)  -&gt; bytes written / &lt;0</span></span>
<span class="line"><span>driver_block_flush(dev)                   -&gt; 0 / &lt;0</span></span>
<span class="line"><span>driver_block_set_ops(dev, ops)</span></span></code></pre></div><p>加上将发现的 PCI 设备绑定到驱动的家族初始化条目：<code>driver_block_ahci_init(pci)</code>、<code>driver_block_nvme_init(pci)</code>、<code>driver_block_ata_dma_init(pci)</code>。</p><h2 id="实现驱动程序" tabindex="-1">实现驱动程序 <a class="header-anchor" href="#实现驱动程序" aria-label="Permalink to &quot;实现驱动程序&quot;">​</a></h2><ol><li>探测你的总线（通过 <code>driver_pci_find_class_mask</code> 进行 PCI 类别匹配）。</li><li>映射 BAR，重置设备，协商特性。</li><li>构建一个操作结构体（以扇区为单位的读写/刷新）并调用 <code>driver_block_register(&quot;myd0&quot;, &amp;ops, ctx)</code> - 实例名称是 <code>dskstat</code> 显示的内容。</li><li>优雅地失败：探测时拒绝并附带消息，胜过静默的部分注册。</li></ol><h2 id="带有约束的规则" tabindex="-1">带有约束的规则 <a class="header-anchor" href="#带有约束的规则" aria-label="Permalink to &quot;带有约束的规则&quot;">​</a></h2><ul><li>DMA 边界：32 位掩码设备必须在探测时和每次传输时拒绝超过 4GiB 的地址（遵循 xHCI 先例）。</li><li>对齐：ATA-DMA PRDT 对齐依赖于堆的 32 字节头保证。</li><li>作为门禁的测试：<code>fstest</code>、<code>disk_rw_test</code>、各驱动的 <code>*_test</code> 命令。</li></ul>`,10)])])}const b=a(s,[["render",o]]);export{h as __pageData,b as default};
